{"source":"import sys,json,math

MAT={'wood':(1.0,),'rubber':(2.0,)}

def send(req):
    try:
        sys.stdout.write(json.dumps(req,separators=(',',':'))+'\n')
        sys.stdout.flush()
        line=sys.stdin.readline()
        if not line:
            return None
        r=json.loads(line)
        return r if isinstance(r,dict) else None
    except Exception:
        return None

def num(v,d=0.0):
    return float(v) if isinstance(v,(int,float)) and not isinstance(v,bool) else d

def find(w,key):
    if not isinstance(w,dict):
        return 0.0
    if key in w:
        return num(w[key])
    for k in ('params','parameters','drawn'):
        if isinstance(w.get(k),dict) and key in w[k]:
            return num(w[k][key])
    return 0.0

def build(r,speed,L,wm):
    wb=L-0.4
    xf=-0.05-r
    xr=xf-wb
    if xr-r<-5.95:
        return None,0
    h=0.2
    y=r+0.01
    dx=(xr+xf)/2
    deck={'shape':'rect','id':'deck','x':round(dx,4),'y':round(y-0.02+h/2,4),'w':round(L,4),'h':h,'angle':0.0,'material':'wood'}
    bodies=[deck]
    joints=[]
    for i,xw in enumerate((xr,xf)):
        bodies.append({'shape':'circle','id':'w%d'%i,'x':round(xw,4),'y':round(y,4),'r':r,'material':wm})
        joints.append({'a':'deck','b':'w%d'%i,'kind':'hinge','x':round(xw,4),'y':round(y,4),'motor_speed':speed})
    cost=L*h*1.0+2*math.pi*r*r*MAT[wm][0]
    return {'language':1,'payload_on':'deck','bodies':bodies,'joints':joints},cost

def main():
    rep=send({'op':'instances'})
    insts=[]
    remaining=0
    if rep and rep.get('ok'):
        insts=rep.get('instances') or []
        remaining=num(rep.get('remaining_steps'))
    default,_=build(0.6,-6.0,3.6,'rubber')
    if not insts:
        send({'op':'submit','design':default})
        return
    budget=None
    for i in insts:
        b=((i.get('world') or {}).get('rules') or {}).get('budget')
        if isinstance(b,(int,float)):
            budget=b if budget is None else min(budget,b)
    def diff(i):
        w=i.get('world') or {}
        return find(w,'gap')+find(w,'step_height')
    insts=sorted(insts,key=diff,reverse=True)
    cands=[]
    for r in (0.6,0.8,0.45,1.0):
        for sp in (-6.0,-10.0,-3.0):
            for L in (3.0,3.8):
                for wm in ('rubber','wood'):
                    d,c=build(r,sp,L,wm)
                    if d is None:
                        continue
                    if budget is not None and c>budget:
                        continue
                    cands.append(d)
    if not cands:
        cands=[default]
    best=None
    bestscore=(-1,-1.0)
    nexp=0
    stop=False
    def run(inst,d):
        nonlocal nexp,remaining,stop
        ms=num(inst.get('max_steps'),2400)
        if nexp>=32 or remaining<ms:
            stop=True
            return None
        nexp+=1
        r=send({'op':'experiment','instance':inst.get('id'),'design':d})
        if not r or not r.get('ok'):
            stop=True
            return None
        rs=r.get('remaining_steps')
        if isinstance(rs,(int,float)):
            remaining=rs
        else:
            remaining-=num(r.get('steps'))
        oc=r.get('outcome')
        if oc=='unknown':
            stop=True
        if oc!='scored':
            return (False,0.0)
        m=r.get('metrics') or {}
        return (bool(m.get('success')),num(m.get('progress')))
    for d in cands:
        if stop:
            break
        res=run(insts[0],d)
        if res is None:
            break
        succ=1 if res[0] else 0
        prog=res[1]
        if res[0]:
            for i in insts[1:]:
                if stop:
                    break
                r2=run(i,d)
                if r2 is None:
                    break
                if r2[0]:
                    succ+=1
        score=(succ,prog)
        if score>bestscore:
            bestscore=score
            best=d
        if succ==len(insts):
            break
    send({'op':'submit','design':best if best is not None else default})

try:
    main()
except Exception:
    pass
sys.exit(0)
"}
